// Get latest file by date in filename
const items = $input.all();

if (items.length === 0) {
  return [];
}

// Sort by filename (date embedded) descending
const sorted = items.sort((a, b) => {
  const nameA = a.json.name || '';
  const nameB = b.json.name || '';
  return nameB.localeCompare(nameA);
});

// Return only the latest file
return [sorted[0]];

// Extract STOCK_BALANCE array from parsed XML
const data = $input.first().json;

// Navigate the XML structure
const stockBalances = data['ns1:StockBalances_Generic']?.STOCK_BALANCE || [];

// Ensure it's an array
const records = Array.isArray(stockBalances) ? stockBalances : [stockBalances];

return {
  json: {
    records: records,
    totalRecords: records.length,
    fileName: $input.first().json.fileName || 'unknown'
  }
};

// Transform stock record to API format
const record = $json;

const sku = record.ProductCode?.trim() || '';
const stockQty = parseFloat(record.UnrestrictedQty) || 0;

return {
  json: {
    sku: sku,
    stock_quantity: Math.floor(stockQty),
    product_description: record.ProductDescription?.trim() || '',
    stock_date: record.StockDate || ''
  }
};

// Get XML content from binary data
const binaryData = $input.first().binary.data;
const xmlContent = Buffer.from(binaryData.data, 'base64').toString('utf-8');

// Extract STOCK_BALANCE records
const stockBalanceRegex = /<STOCK_BALANCE>([\s\S]*?)<\/STOCK_BALANCE>/g;
const records = [];

let match;
while ((match = stockBalanceRegex.exec(xmlContent)) !== null) {
  const recordXml = match[1];

  const productCode = (recordXml.match(/<ProductCode>(.*?)<\/ProductCode>/) || [])[1] || '';
  const productDescription = (recordXml.match(/<ProductDescription>(.*?)<\/ProductDescription>/) || [])[1] || '';
  const stockDate = (recordXml.match(/<StockDate>(.*?)<\/StockDate>/) || [])[1] || '';
  const unrestrictedQty = (recordXml.match(/<UnrestrictedQty>(.*?)<\/UnrestrictedQty>/) || [])[1] || '0';

  records.push({
    ProductCode: productCode.trim(),
    ProductDescription: productDescription.trim(),
    StockDate: stockDate.trim(),
    UnrestrictedQty: parseFloat(unrestrictedQty.trim()) || 0
  });
}

return records.map(record => ({ json: record }));

