// Process each search result with its corresponding XML data
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const searchResult = items[i].json;
  const records = searchResult.records || [];
  const originalData = $('Parse Drive XML').all()[i].json;

  console.log(`Processing item ${i + 1}: ${originalData.ProductDescription}`);
  console.log(`Search found ${records.length} records`);

  // Check if any record matches the product name exactly
  const existingProduct = records.find(r => {
    const props = r.properties || {};
    const nameMatch = props.product_name?.toLowerCase() === originalData.ProductDescription?.toLowerCase();
    const skuMatch = props.sku === originalData.ProductCode || props.product_code === originalData.ProductCode;

    console.log(`  Checking: ${props.product_name}, Name match: ${nameMatch}, SKU match: ${skuMatch}`);

    return nameMatch || skuMatch;
  });

  if (existingProduct) {
    console.log(`  -> Product EXISTS - will UPDATE (ID: ${existingProduct.id})`);
    results.push({
      json: {
        action: 'update',
        productId: existingProduct.id,
        sku: originalData.ProductCode,
        product_code: originalData.ProductCode,
        product_name: originalData.ProductDescription,
        product_description: originalData.ProductDescription,
        uncommitted_stock: Math.floor(originalData.UnrestrictedQty).toString(),
        awaiting_put_away: Math.floor(originalData.QualityQty).toString(),
        stock_holding: Math.floor(originalData.BlockedQty).toString(),
        on_po: Math.floor(originalData.OnOrderQty).toString(),
        preorder_qty: Math.floor(originalData.BookQty).toString(),
        stock_date: originalData.StockDate
      }
    });
  } else {
    console.log(`  -> Product NOT FOUND - will CREATE`);
    results.push({
      json: {
        action: 'create',
        sku: originalData.ProductCode,
        product_code: originalData.ProductCode,
        product_name: originalData.ProductDescription,
        product_description: originalData.ProductDescription,
        uncommitted_stock: Math.floor(originalData.UnrestrictedQty).toString(),
        awaiting_put_away: Math.floor(originalData.QualityQty).toString(),
        stock_holding: Math.floor(originalData.BlockedQty).toString(),
        on_po: Math.floor(originalData.OnOrderQty).toString(),
        preorder_qty: Math.floor(originalData.BookQty).toString(),
        stock_date: originalData.StockDate
      }
    });
  }
}

return results;

// Get XML content from webhook
let xmlContent = '';
const input = $input.first();

console.log('Input keys:', Object.keys(input));
console.log('JSON keys:', Object.keys(input.json || {}));
console.log('Binary keys:', Object.keys(input.binary || {}));

// Check if data is in binary format (file upload)
if (input.binary && Object.keys(input.binary).length > 0) {
  const binaryKey = Object.keys(input.binary)[0];
  console.log('Reading from binary key:', binaryKey);
  const xmlBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  xmlContent = xmlBuffer.toString('utf-8');
} 
// Check if XML is in body as string
else if (input.json.body && typeof input.json.body === 'string') {
  xmlContent = input.json.body;
}
// Check if there's a file field in the form data
else if (input.json.file && typeof input.json.file === 'string') {
  xmlContent = input.json.file;
}
// Check if XML is directly in the webhook data
else if (input.json.xmlContent && typeof input.json.xmlContent === 'string') {
  xmlContent = input.json.xmlContent;
}
// Check all json fields for XML-like content
else {
  for (const key in input.json) {
    const value = input.json[key];
    if (typeof value === 'string' && value.includes('<STOCK_BALANCE>')) {
      console.log('Found XML in field:', key);
      xmlContent = value;
      break;
    }
  }
}

// Ensure xmlContent is a string
if (typeof xmlContent !== 'string') {
  console.log('Data type:', typeof xmlContent);
  console.log('Full input:', JSON.stringify(input.json, null, 2));
  throw new Error('Could not find XML content in webhook payload');
}

console.log('XML Content length:', xmlContent.length);
console.log('XML Content preview:', xmlContent.substring(0, 300));

const stockBalanceRegex = /<STOCK_BALANCE>([\s\S]*?)<\/STOCK_BALANCE>/g;
const records = [];

let match;
while ((match = stockBalanceRegex.exec(xmlContent)) !== null) {
  const recordXml = match[1];

  const productCode = (recordXml.match(/<ProductCode>(.*?)<\/ProductCode>/) || [])[1] || '';
  const productDescription = (recordXml.match(/<ProductDescription>(.*?)<\/ProductDescription>/) || [])[1] || '';
  const stockDate = (recordXml.match(/<StockDate>(.*?)<\/StockDate>/) || [])[1] || '';
  const unrestrictedQty = (recordXml.match(/<UnrestrictedQty>(.*?)<\/UnrestrictedQty>/) || [])[1] || '0';
  const qualityQty = (recordXml.match(/<QualityQty>(.*?)<\/QualityQty>/) || [])[1] || '0';
  const blockedQty = (recordXml.match(/<BlockedQty>(.*?)<\/BlockedQty>/) || [])[1] || '0';
  const onOrderQty = (recordXml.match(/<OnOrderQty>(.*?)<\/OnOrderQty>/) || [])[1] || '0';
  const bookQty = (recordXml.match(/<BookQty>(.*?)<\/BookQty>/) || [])[1] || '0';

  records.push({
    ProductCode: productCode.trim(),
    ProductDescription: productDescription.trim(),
    StockDate: stockDate.trim(),
    UnrestrictedQty: parseFloat(unrestrictedQty.trim()) || 0,
    QualityQty: parseFloat(qualityQty.trim()) || 0,
    BlockedQty: parseFloat(blockedQty.trim()) || 0,
    OnOrderQty: parseFloat(onOrderQty.trim()) || 0,
    BookQty: parseFloat(bookQty.trim()) || 0
  });
}

console.log('Records found:', records.length);

if (records.length === 0) {
  throw new Error('No STOCK_BALANCE records found. Check console for XML preview.');
}

return records.map(record => ({ json: record }));
